import java.util.Scanner;

public class Main {
    static long[] arr = new long[17];

    static long recursiveFunc(long n, int index) {
        long count = n / arr[index];
        n %= arr[index];
        if (n == 0) return count * index;
        else return count * index + Math.min(index + recursiveFunc(arr[index] - n, index - 1), recursiveFunc(n, index - 1));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long number;
        arr[0] = 0;
        for (int i = 1; i <= 16; ++i) {
            arr[i] = arr[i - 1] * 10 + 1;
        }
        number = sc.nextLong();
        System.out.println(recursiveFunc(number, 16));
        sc.close();
    }
}
